190: /**
191:  * Executes a native Node.js HTTP/HTTPS request with timeout and redirect following.
192:  * Fully compatible with Node.js 12.22.2 (no fetch, no AbortController, zero dependencies).
193:  *
194:  * @param {string} urlStr
195:  * @param {object} [options]
196:  * @param {string} [options.method='GET']
197:  * @param {object} [options.headers]
198:  * @param {Buffer|string} [options.body]
199:  * @param {number} [options.timeout=10000]
200:  * @param {number} [options.maxRedirects=5]
201:  * @returns {Promise<{ statusCode: number, status: number, ok: boolean, headers: object, body: Buffer, url: string }>}
202:  */
203: function request(urlStr, options) {
204:   options = options || {};
205:   const method = (options.method || 'GET').toUpperCase();
206:   const headers = Object.assign({}, options.headers || {});
207:   const timeout = typeof options.timeout === 'number' ? options.timeout : 10000;
208:   const maxRedirects = typeof options.maxRedirects === 'number' ? options.maxRedirects : 5;
209:   const body = options.body;
210: 
211:   return new Promise((resolve, reject) => {
212:     let parsed;
213:     try {
214:       parsed = new URL(urlStr);
215:     } catch (err) {
216:       return reject(new Error('Invalid URL: ' + urlStr));
217:     }
218: 
219:     const client = parsed.protocol === 'https:' ? https : http;
220:     const reqOpts = {
221:       protocol: parsed.protocol,
222:       hostname: parsed.hostname,
223:       port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80),
224:       path: parsed.pathname + parsed.search,
225:       method: method,
226:       headers: headers
227:     };
228: 
229:     if (body) {
230:       if (!headers['Content-Length'] && !headers['content-length']) {
231:         headers['Content-Length'] = Buffer.isBuffer(body) ? body.length : Buffer.byteLength(body);
232:       }
233:     }
234: 
235:     const req = client.request(reqOpts, (res) => {
236:       const statusCode = res.statusCode;
237: 
238:       // Handle transparent redirects
239:       if ([301, 302, 303, 307, 308].indexOf(statusCode) !== -1 && res.headers.location && maxRedirects > 0) {
240:         res.resume(); // Drain existing stream
241:         const nextUrl = new URL(res.headers.location, urlStr).href;
242:         const nextOpts = Object.assign({}, options, { maxRedirects: maxRedirects - 1 });
243:         if (statusCode === 303 && method !== 'HEAD') {
244:           nextOpts.method = 'GET';
245:           delete nextOpts.body;
246:         }
247:         return resolve(request(nextUrl, nextOpts));
248:       }
249: 
250:       const chunks = [];
251:       res.on('data', (chunk) => chunks.push(chunk));
252:       res.on('end', () => {
253:         resolve({
254:           statusCode: statusCode,
255:           status: statusCode,
256:           ok: statusCode >= 200 && statusCode < 300,
257:           headers: res.headers,
258:           body: Buffer.concat(chunks),
259:           url: urlStr
260:         });
261:       });
262:     });
263: 
264:     req.on('error', reject);
265: 
266:     if (timeout > 0) {
267:       req.setTimeout(timeout, () => {
268:         req.abort();
269:         reject(new Error('Request timed out after ' + timeout + 'ms (' + urlStr + ')'));
270:       });
271:     }
272: 
273:     if (body) {
274:       req.write(body);
275:     }
276:     req.end();
277:   });
278: }
279: 
280: /**
281:  * Performs GET request and parses JSON body.
282:  *
283:  * @param {string} urlStr
284:  * @param {object} [options]
285:  * @returns {Promise<any>}
286:  */
287: function getJson(urlStr, options) {
288:   return request(urlStr, options).then((res) => {
289:     if (res.statusCode < 200 || res.statusCode >= 300) {
290:       throw new Error('HTTP ' + res.statusCode + ' for ' + urlStr);
291:     }
292:     return JSON.parse(res.body.toString('utf8'));
293:   });
294: }
295: 
296: /**
297:  * Performs GET request and returns decoded text string.
298:  *
299:  * @param {string} urlStr
300:  * @param {object} [options]
301:  * @returns {Promise<string>}
302:  */
303: function getText(urlStr, options) {
304:   return request(urlStr, options).then((res) => {
305:     if (res.statusCode < 200 || res.statusCode >= 300) {
306:       throw new Error('HTTP ' + res.statusCode + ' for ' + urlStr);
307:     }
308:     return res.body.toString('utf8');
309:   });
310: }
311: 
312: module.exports = {
313:   request: request,
314:   getJson: getJson,
315:   getText: getText
316: };
