  const maxRedirects = typeof options.maxRedirects === 'number' ? options.maxRedirects : 5;
  const body = options.body;

  return new Promise((resolve, reject) => {
    let parsed;
    try {
      parsed = new URL(urlStr);
    } catch (err) {
      return reject(new Error('Invalid URL: ' + urlStr));
    }

    const client = parsed.protocol === 'https:' ? https : http;
    const reqOpts = {
      protocol: parsed.protocol,
      hostname: parsed.hostname,
      port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80),
      path: parsed.pathname + parsed.search,
      method: method,
      headers: headers
    };

    if (body) {
      if (!headers['Content-Length'] && !headers['content-length']) {
        headers['Content-Length'] = Buffer.isBuffer(body) ? body.length : Buffer.byteLength(body);
      }
    }

    const req = client.request(reqOpts, (res) => {
      const statusCode = res.statusCode;

      // Handle transparent redirects
      if ([301, 302, 303, 307, 308].indexOf(statusCode) !== -1 && res.headers.location && maxRedirects > 0) {
        res.resume(); // Drain existing stream
        const nextUrl = new URL(res.headers.location, urlStr).href;
        const nextOpts = Object.assign({}, options, { maxRedirects: maxRedirects - 1 });
        if (statusCode === 303 && method !== 'HEAD') {
          nextOpts.method = 'GET';
          delete nextOpts.body;
        }
        return resolve(request(nextUrl, nextOpts));
      }

      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          statusCode: statusCode,
          status: statusCode,
          ok: statusCode >= 200 && statusCode < 300,
          headers: res.headers,
          body: Buffer.concat(chunks),
          url: urlStr
        });
      });
    });

    req.on('error', reject);

    if (timeout > 0) {
      req.setTimeout(timeout, () => {
        req.abort();
        reject(new Error('Request timed out after ' + timeout + 'ms (' + urlStr + ')'));
      });
    }

    if (body) {
      req.write(body);
    }
    req.end();
  });
}

/**
 * Performs GET request and parses JSON body.
 *
 * @param {string} urlStr
 * @param {object} [options]
 * @returns {Promise<any>}
 */
function getJson(urlStr, options) {
  return request(urlStr, options).then((res) => {
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw new Error('HTTP ' + res.statusCode + ' for ' + urlStr);
    }
    return JSON.parse(res.body.toString('utf8'));
  });
}

/**
 * Performs GET request and returns decoded text string.
 *
 * @param {string} urlStr
 * @param {object} [options]
 * @returns {Promise<string>}
 */
function getText(urlStr, options) {
  return request(urlStr, options).then((res) => {
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw new Error('HTTP ' + res.statusCode + ' for ' + urlStr);
    }
    return res.body.toString('utf8');
  });
}

module.exports = {
  request: request,
  getJson: getJson,
  getText: getText
};

/**
 * poc/service/resolver.js - Stream Resolver Engine for com.cinejoy.poc.service
 * 
 * Executes WebAssembly crush.wasm request sealing, binary POST to api.wing.st/g,
 * AES-256-GCM response decryption, and multi-server fallback resolution.
 * Fully compatible with Node.js 12.22.2 (no fetch, no modern operators, zero dependencies).
 */

'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const httpClient = require('./http-client');

// Protocol Constants
const PROTOCOL_ID = 'lumen-gate-v2';
const RANDOM_SEED_LEN = 44;
const AES_KEY_LEN = 32;
const KEY_ID_LEN = 1;
const EC_PUBKEY_LEN = 65;
const HEADER_LEN = 98; // 32 + 1 + 65
const GCM_IV_LEN = 12;
const GCM_TAG_LEN = 16;
const OUT_BUF_MAX = 4096;

const GATEWAY_URL = 'https://api.wing.st/g';
const SERVERS_URL = 'https://api.wing.st/servers';
const WASM_REMOTE_URL = 'https://api.wing.st/crush.wasm';
const SUBS_URL = 'https://subs.wing.st/subtitles';

const SERVERS_CACHE_TTL_MS = 300000; // 5 minutes

// State Caches
let cachedWasmModule = null;
let cachedServersData = null;
let lastServersFetchTime = 0;

/**
 * Loads and compiles the crush.wasm WebAssembly module.
 * Prioritizes local disk file, falls back to remote download via http-client.
 * 
 * @param {string} [customPath] - Optional custom path to crush.wasm
 * @returns {Promise<WebAssembly.Module>} Compiled WebAssembly module
 */
async function initWasm(customPath) {
  if (cachedWasmModule) {
    return cachedWasmModule;
  }

  const defaultPath = path.resolve(__dirname, 'crush.wasm');
  const wasmPath = customPath || defaultPath;

  let wasmBuffer;
  if (fs.existsSync(wasmPath)) {
    wasmBuffer = fs.readFileSync(wasmPath);
  } else {
    // Fallback: fetch from remote endpoint using native http-client
    const res = await httpClient.request(WASM_REMOTE_URL, { timeout: 10000 });
    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw new Error('Failed to download crush.wasm: HTTP ' + res.statusCode);
    }
    wasmBuffer = res.body;
    try {
      fs.writeFileSync(wasmPath, wasmBuffer);
    } catch (_) {
      // Ignore write errors in read-only filesystems
    }
  }

  cachedWasmModule = await WebAssembly.compile(wasmBuffer);
  return cachedWasmModule;
}

/**
 * Retrieves the active streaming server cluster list.
 * 
 * @param {boolean} [forceRefresh=false] - Force bypass cache
 * @returns {Promise<{ servers: Array<object> }>} Cluster servers response object
 */
async function getServers(forceRefresh) {
  const now = Date.now();
  if (!forceRefresh && cachedServersData && (now - lastServersFetchTime < SERVERS_CACHE_TTL_MS)) {
    return cachedServersData;
  }

  try {
    const data = await httpClient.getJson(SERVERS_URL, {
      timeout: 5000,
      headers: {
        'Origin': 'https://cinejoy.pk',
        'Referer': 'https://cinejoy.pk/',
        'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/108.0.5359.211 Safari/537.36'
      }
    });
    cachedServersData = {
      servers: Array.isArray(data.servers) ? data.servers : []
    };
    lastServersFetchTime = now;
    return cachedServersData;
  } catch (err) {
    if (cachedServersData) {
      return cachedServersData; // Use stale cache on error
    }
    // Hardcoded fallback if endpoint is unreachable
    cachedServersData = {
      servers: [
        { name: 'secret', status: 'ok', '4k': true },
        { name: 'Nebula', status: 'ok', '4k': false },
        { name: 'Lisbon', status: 'ok', '4k': true },
        { name: 'Solara', status: 'ok', '4k': false },
        { name: 'Athens', status: 'ok', '4k': false }
      ]
    };
    return cachedServersData;
  }
}

/**
 * Executes request sealing in crush.wasm.
 * 
 * @param {WebAssembly.Instance} wasmInstance
 * @param {object} params
 * @returns {{ responseKey: Buffer, keyId: number, ephemeralPublic: Buffer, ciphertextBody: Buffer }}
 */
function sealRequest(wasmInstance, params) {
  const server = params.server;
  const type = params.type;
  const tmdbId = params.tmdbId;
  const season = params.season;
  const episode = params.episode;

  const exports = wasmInstance.exports;
  const wasmType = (type === 'tv' || type === 'series') ? 'series' : 'movie';

  const payloadObj = { tmdb: String(tmdbId) };
  if (wasmType === 'series') {
    payloadObj.season = String(season || 1);
    payloadObj.episode = String(episode || 1);
  }

  const payloadJson = JSON.stringify({
    path: '/' + server + '/' + wasmType,
    payload: payloadObj
  });

  const encodedPayload = Buffer.from(payloadJson, 'utf8');
  const randBytes = crypto.randomBytes(RANDOM_SEED_LEN);

  const payloadPtr = exports.alloc(encodedPayload.length);
  const randPtr = exports.alloc(randBytes.length);
  const outPtr = exports.alloc(OUT_BUF_MAX);

  const mem = new Uint8Array(exports.memory.buffer);
  mem.set(encodedPayload, payloadPtr);
  mem.set(randBytes, randPtr);

  const sealedLen = exports.seal_request(
    payloadPtr, encodedPayload.length,
    randPtr, randBytes.length,
    outPtr, OUT_BUF_MAX
  );

  if (sealedLen <= HEADER_LEN) {
    exports.dealloc(payloadPtr, encodedPayload.length);
    exports.dealloc(randPtr, randBytes.length);
    exports.dealloc(outPtr, OUT_BUF_MAX);
    throw new Error('WASM seal_request returned invalid length: ' + sealedLen);
  }

  const sealedBuffer = Buffer.from(exports.memory.buffer, outPtr, sealedLen);
  const responseKey = Buffer.from(sealedBuffer.subarray(0, AES_KEY_LEN));
  const keyId = sealedBuffer[AES_KEY_LEN];
  const ephemeralPublic = Buffer.from(sealedBuffer.subarray(AES_KEY_LEN + KEY_ID_LEN, HEADER_LEN));
  const ciphertextBody = Buffer.from(sealedBuffer.subarray(HEADER_LEN, sealedLen));

  // Free allocated linear memory
  exports.dealloc(payloadPtr, encodedPayload.length);
  exports.dealloc(randPtr, randBytes.length);
  exports.dealloc(outPtr, OUT_BUF_MAX);

  return { responseKey: responseKey, keyId: keyId, ephemeralPublic: ephemeralPublic, ciphertextBody: ciphertextBody };
}

/**
 * Decrypts AES-256-GCM gateway response using Node.js crypto.
 * 
 * @param {Buffer} respBuf - Raw response from api.wing.st/g
 * @param {Buffer} responseKey - 32-byte AES key
 * @param {number} keyId - Key version byte
 * @param {Buffer} ephemeralPublic - 65-byte public key
 * @returns {object} Decoded JSON response
 */
function decryptResponse(respBuf, responseKey, keyId, ephemeralPublic) {
  if (respBuf.length < GCM_IV_LEN + GCM_TAG_LEN) {
    throw new Error('Gateway response buffer too short: ' + respBuf.length + ' bytes (minimum 28 required)');
  }

  const iv = respBuf.subarray(0, GCM_IV_LEN);
  const authTag = respBuf.subarray(respBuf.length - GCM_TAG_LEN);
  const ciphertext = respBuf.subarray(GCM_IV_LEN, respBuf.length - GCM_TAG_LEN);

  const aad = Buffer.concat([
    Buffer.from(PROTOCOL_ID, 'utf8'),
    Buffer.from([0, 2, keyId]),
    ephemeralPublic
  ]);

  const decipher = crypto.createDecipheriv('aes-256-gcm', responseKey, iv);
  decipher.setAAD(aad);
  decipher.setAuthTag(authTag);

  const decrypted = Buffer.concat([
    decipher.update(ciphertext),
    decipher.final()
  ]);

  return JSON.parse(decrypted.toString('utf8'));
}

/**
 * Attempts stream resolution on a single named server node.
 * 
 * @private
 */
async function resolveSingleServer(params) {
  const server = params.server;
  const type = params.type;
  const tmdbId = params.tmdbId;
  const season = params.season;
  const episode = params.episode;
  const wasmModule = params.wasmModule;

  const instance = await WebAssembly.instantiate(wasmModule);
  const sealed = sealRequest(instance, {
    server: server,
    type: type,
    tmdbId: tmdbId,
    season: season,
    episode: episode
  });

  const gatewayRes = await httpClient.request(GATEWAY_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'text/plain;charset=UTF-8',
      'Origin': 'https://cinejoy.pk',
      'Referer': 'https://cinejoy.pk/',
      'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/108.0.5359.211 Safari/537.36'
    },
    body: sealed.ciphertextBody,
    timeout: 10000
  });

  if (gatewayRes.statusCode < 200 || gatewayRes.statusCode >= 300) {
    throw new Error('Gateway returned HTTP ' + gatewayRes.statusCode);
  }

  const decrypted = decryptResponse(gatewayRes.body, sealed.responseKey, sealed.keyId, sealed.ephemeralPublic);

  if (decrypted.status !== 200) {
    const errorMsg = (decrypted.data && decrypted.data.error) ? decrypted.data.error : ('Status ' + decrypted.status);
    throw new Error(server + ': ' + errorMsg);
  }

  const stream = (decrypted.data && decrypted.data.stream && decrypted.data.stream[0]) ? decrypted.data.stream[0] : null;
  if (!stream || !stream.playlist) {
    throw new Error(server + ': No playable playlist returned');
  }

  return {
    playlist: stream.playlist,
    captions: stream.captions || [],
    server: server,
    rawStream: stream
  };
}

/**
 * Main export: Resolves stream with multi-server fallback.
 * 
 * @param {object} options
 * @returns {Promise<{ success: boolean, playlist: string, originalUrl: string, streamUrl: string, server: string, format: string, captions: Array, rawStream: object }>}
 */
async function resolveStream(options) {
  const tmdbId = options.tmdbId;
  const type = options.type || 'movie';
  const season = options.season;
  const episode = options.episode;
  const server = options.server || 'secret';
  const fallback = options.fallback !== false;

  if (!tmdbId) {
    throw new Error('tmdbId is required for stream resolution');
  }

  const wasmModule = await initWasm();
  const clusterData = await getServers();
  const serverList = Array.isArray(clusterData.servers) ? clusterData.servers : [];
  const serverNames = serverList.map(function (s) { return s.name; });

  // If cluster list is empty, supply default known servers
  if (serverNames.length === 0) {
    serverNames.push('secret', 'Nebula', 'Lisbon', 'Solara', 'Athens');
  }

  // Build candidate order: preferred server first if specified
  const candidates = [];
  if (server && server !== 'auto' && serverNames.indexOf(server) !== -1) {
    candidates.push(server);
  }
  for (let i = 0; i < serverNames.length; i++) {
    const s = serverNames[i];
    if (candidates.indexOf(s) === -1) {
      candidates.push(s);
    }
  }

  const errors = [];
  for (let j = 0; j < candidates.length; j++) {
    const candidate = candidates[j];
    try {
      const result = await resolveSingleServer({
        server: candidate,
        type: type,
        tmdbId: tmdbId,
        season: season,
        episode: episode,
        wasmModule: wasmModule
      });

      return {
        success: true,
        playlist: result.playlist,
        originalUrl: result.playlist,
        streamUrl: result.playlist,
        server: result.server,
        format: 'hls',
        captions: result.captions,
        rawStream: result.rawStream
      };
    } catch (err) {
      errors.push(err.message);
      if (!fallback) {
        throw new Error('Failed to resolve on ' + candidate + ': ' + err.message);
      }
    }
  }

  throw new Error('All servers failed to resolve stream for ' + type + ' ' + tmdbId + ':\n  ' + errors.join('\n  '));
}

/**
 * Queries external subtitles from subs.wing.st.
 * 
 * @param {object} options
 * @returns {Promise<Array<{ id: string, language: string, url: string }>>}
 */
async function fetchSubtitles(options) {
  const tmdbId = options.tmdbId;
  const type = options.type || 'movie';
  const season = options.season;
  const episode = options.episode;

  const subsType = (type === 'tv' || type === 'series') ? 'tv' : 'movie';
  let url = SUBS_URL + '?type=' + subsType + '&tmdb=' + tmdbId;
  if (subsType === 'tv') {
    url += '&season=' + (season || 1) + '&episode=' + (episode || 1);
  }

  try {
    const data = await httpClient.getJson(url, {
      timeout: 5000,
      headers: {
        'Origin': 'https://cinejoy.pk',
        'Referer': 'https://cinejoy.pk/'
      }
    });
    return data.subtitles || [];
  } catch (_) {
    return [];
  }
}

module.exports = {
  resolveStream: resolveStream,
  getServers: getServers,
  fetchSubtitles: fetchSubtitles,
  initWasm: initWasm,
  sealRequest: sealRequest,
  decryptResponse: decryptResponse
};

/**
 * poc/service/hls-proxy.js
 * 
 * High-performance HLS Manifest Rewriter & fMP4 Media Segment Streaming Proxy.
 * Built with native Node.js built-ins for LG webOS TV (Node 12.22.2, Chromium WAM).
 * 
 * Features:
 * - Strict Node 12 compatibility (no ?., no ??, no Readable.fromWeb, no AbortController).
 * - Injects Origin: https://cinejoy.pk and Referer: https://cinejoy.pk/ headers.
 * - Rewrites master and variant playlists (M3U8) with absolute URL resolution.
 * - Zero-buffering stream pipeline for fMP4 (.png/.mp4) chunks directly from TCP socket.
 * - Full Range request support (HTTP 206 Partial Content).
 * - Client disconnect cleanup (req.on('close')).
 */

'use strict';

const http = require('http');
const https = require('https');
const { pipeline } = require('stream');
const { URL } = require('url');

/**
 * Standard upstream headers required by Lightspeed CDN and Nebula CDN.
 */
const UPSTREAM_HEADERS = {
  'Origin': 'https://cinejoy.pk',
  'Referer': 'https://cinejoy.pk/',
  'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/108.0.5359.211 Safari/537.36',
  'Accept': '*/*'
};

/**
 * Common CORS and streaming headers applied to all proxy responses.
 */
const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',
  'Access-Control-Allow-Headers': '*',
  'Access-Control-Expose-Headers': 'Content-Length, Content-Range, Accept-Ranges, Content-Type',
  'Accept-Ranges': 'bytes'
};

/**
 * Resolves a raw URI from an M3U8 manifest against a base URL.
 * 
 * @param {string} rawUri - The relative, root-relative, or absolute URI.
 * @param {string} baseUrl - The base URL (post-redirect) of the manifest.
 * @returns {string} The fully-qualified absolute URL.
 */
function resolveUrl(rawUri, baseUrl) {
  try {
    return new URL(rawUri, baseUrl).href;
  } catch (err) {
    return rawUri;
  }
}

/**
 * Unwraps an existing proxy URL to ensure rewriting is idempotent.
 * 
 * @param {string} urlStr - The candidate URL string.
 * @returns {string} The original unwrapped target URL.
 */
function unwrapProxyUrl(urlStr) {
  try {
    const parsed = new URL(urlStr);
    if (parsed.pathname === '/hls/proxy' && parsed.searchParams.has('url')) {
      return parsed.searchParams.get('url');
    }
  } catch (_) {
    // Ignore URL parse errors
  }
  return urlStr;
}

/**
 * Determines whether a URL or response corresponds to an HLS playlist.
 * 
 * @param {string} urlStr - Target URL.
 * @param {string} [contentType] - Content-Type header from upstream response.
 * @returns {boolean} True if the resource is an M3U8 playlist.
 */
function isPlaylistResource(urlStr, contentType) {
  contentType = contentType || '';
  try {
    const pathname = new URL(urlStr).pathname.toLowerCase();
    if (pathname.endsWith('.m3u8')) return true;
    if (contentType && (contentType.indexOf('application/vnd.apple.mpegurl') !== -1 || contentType.indexOf('application/x-mpegurl') !== -1)) {
      return true;
    }
    // Handle edge cases where variant playlists have extensions like .jpg on secondary servers
    if (pathname.endsWith('/master') || pathname.endsWith('/playlist') || /playlist\.[a-z0-9]+$/i.test(pathname)) {
      return true;
    }
  } catch (_) {
    // Ignore parse error
  }
  return false;
}

/**
 * Rewrites an M3U8 manifest, updating all playlist and segment URIs to route through /hls/proxy.
 * 
 * @param {string} manifestText - The raw M3U8 manifest content.
 * @param {string} baseUrl - The final post-redirect URL of the manifest.
 * @param {string} proxyPrefix - The local proxy prefix (e.g. 'http://127.0.0.1:8088/hls/proxy?url=').
 * @returns {string} The rewritten M3U8 content.
 */
function rewriteManifest(manifestText, baseUrl, proxyPrefix) {
  const lines = manifestText.split(/\r?\n/);

  const rewrittenLines = lines.map(function (line) {
    const trimmed = line.trim();
    if (!trimmed) return line;

    // 1. Process tags with URI="..." or X-ASSET-URI="..." attributes
    if (trimmed.startsWith('#EXT-X-MEDIA:') ||
        trimmed.startsWith('#EXT-X-MAP:') ||
        trimmed.startsWith('#EXT-X-KEY:') ||
        trimmed.startsWith('#EXT-X-I-FRAME-STREAM-INF:') ||
        trimmed.startsWith('#EXT-X-PRELOAD-HINT:') ||
        trimmed.startsWith('#EXT-X-RENDITION-REPORT:') ||
        trimmed.startsWith('#EXT-X-DATERANGE:')) {
      return line.replace(/\b([A-Z0-9-]*URI)=(["'])(.*?)\2/g, function (match, attrName, quote, rawUri) {
        const absolute = resolveUrl(rawUri, baseUrl);
        const proxied = proxyPrefix + encodeURIComponent(unwrapProxyUrl(absolute));
        return attrName + '="' + proxied + '"';
      });
    }

    // 2. Preserve non-URI tags and comments
    if (trimmed.startsWith('#')) {
      return line;
    }

    // 3. Process standalone segment or variant playlist URI lines
    const absolute = resolveUrl(trimmed, baseUrl);
    return proxyPrefix + encodeURIComponent(unwrapProxyUrl(absolute));
  });

  return rewrittenLines.join('\n');
}

/**
 * Validates a target URL for protocol correctness and SSRF protection.
 * 
 * @param {string} targetUrlStr - The URL to validate.
 * @returns {{ valid: boolean, error?: string, url?: URL }}
 */
function validateTargetUrl(targetUrlStr) {
  if (!targetUrlStr) {
    return { valid: false, error: 'Missing "url" query parameter' };
  }

  let parsed;
  try {
    parsed = new URL(targetUrlStr);
  } catch (err) {
    return { valid: false, error: 'Invalid URL format' };
  }

  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return { valid: false, error: 'Only http and https protocols are supported' };
  }

  // SSRF Protection: Disallow loopback / internal IPs in production unless testing
  const hostname = parsed.hostname.toLowerCase();
  const isLoopback = hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '0.0.0.0' || hostname === '::1';
  if (process.env.NODE_ENV === 'production' && isLoopback) {
    return { valid: false, error: 'Access to loopback address forbidden' };
  }

  return { valid: true, url: parsed };
}

/**
 * Computes the local proxy URL prefix based on incoming request Host header or localPort.
 * 
 * @param {import('http').IncomingMessage} req - The incoming HTTP request.
 * @param {number} [localPort] - Optional active server port.
 * @returns {string} The proxy prefix (e.g. 'http://127.0.0.1:8088/hls/proxy?url=').
 */
function getProxyPrefix(req, localPort) {
  const host = (req && req.headers && req.headers.host) || (localPort ? ('127.0.0.1:' + localPort) : null) || '127.0.0.1:8088';
  return 'http://' + host + '/hls/proxy?url=';
}

/**
 * Main HTTP request handler for the /hls/proxy endpoint.
 * 
 * @param {import('http').IncomingMessage} req - Client request.
 * @param {import('http').ServerResponse} res - Client response.
 * @param {string} [explicitTargetUrl] - Optional target URL passed from caller.
 * @param {number} [localPort] - Optional active server port.
 */
function handleHlsProxy(req, res, explicitTargetUrl, localPort) {
  // 1. Handle CORS Preflight
  if (req.method === 'OPTIONS') {
    res.writeHead(204, CORS_HEADERS);
    res.end();
    return;
  }

  // 2. Extract and validate target URL
  let rawTargetUrl = explicitTargetUrl;
  if (!rawTargetUrl) {
    try {
      const host = (req && req.headers && req.headers.host) || '127.0.0.1:8088';
      const parsedReqUrl = new URL(req.url, 'http://' + host);
      rawTargetUrl = parsedReqUrl.searchParams.get('url');
    } catch (_) {}
  }

  const validation = validateTargetUrl(rawTargetUrl);
  if (!validation.valid) {
    res.writeHead(400, Object.assign({}, CORS_HEADERS, { 'Content-Type': 'application/json' }));
    res.end(JSON.stringify({ error: validation.error }));
    return;
  }

  const targetUrl = validation.url.href;

  // 3. Client disconnect cleanup: destroy upstream socket if client closes
  let upstreamReq = null;
  req.on('close', function () {
    if (!res.writableEnded && upstreamReq) {
      upstreamReq.destroy();
    }
  });

  // 4. Construct outbound request headers
  const outboundHeaders = Object.assign({}, UPSTREAM_HEADERS);
  if (req.headers && req.headers.range) outboundHeaders['Range'] = req.headers.range;
  if (req.headers && req.headers['if-none-match']) outboundHeaders['If-None-Match'] = req.headers['if-none-match'];
  if (req.headers && req.headers['if-modified-since']) outboundHeaders['If-Modified-Since'] = req.headers['if-modified-since'];

  // 5. Streaming upstream request executor with redirect following
  function executeRequest(currentUrl, redirectCount) {
    if (redirectCount > 5) {
      res.writeHead(502, Object.assign({}, CORS_HEADERS, { 'Content-Type': 'application/json' }));
      return res.end(JSON.stringify({ error: 'Too many redirects', url: currentUrl }));
    }

    let parsed;
    try {
      parsed = new URL(currentUrl);
    } catch (err) {
      res.writeHead(400, Object.assign({}, CORS_HEADERS, { 'Content-Type': 'application/json' }));
      return res.end(JSON.stringify({ error: 'Invalid URL: ' + currentUrl }));
    }

    const client = parsed.protocol === 'https:' ? https : http;
    const reqOpts = {
      protocol: parsed.protocol,
      hostname: parsed.hostname,
      port: parsed.port || (parsed.protocol === 'https:' ? 443 : 80),
      path: parsed.pathname + parsed.search,
      method: req.method || 'GET',
      headers: outboundHeaders
    };

    upstreamReq = client.request(reqOpts, function (upstreamRes) {
      const statusCode = upstreamRes.statusCode;

      // Handle Redirects (301, 302, 303, 307, 308)
      if ([301, 302, 303, 307, 308].indexOf(statusCode) !== -1 && upstreamRes.headers.location) {
        upstreamRes.resume(); // Drain and discard
        const nextUrl = new URL(upstreamRes.headers.location, currentUrl).href;
        return executeRequest(nextUrl, redirectCount + 1);
      }

      // Handle 304 Not Modified
      if (statusCode === 304) {
        res.writeHead(304, CORS_HEADERS);
        return res.end();
      }

      // Handle Upstream Errors (404, 500, etc.)
      if (statusCode !== 200 && statusCode !== 206) {
        res.writeHead(statusCode, Object.assign({}, CORS_HEADERS, { 'Content-Type': 'application/json' }));
        return res.end(JSON.stringify({
          error: 'Upstream CDN error',
          status: statusCode,
          url: currentUrl
        }));
      }

      const upstreamContentType = upstreamRes.headers['content-type'] || '';
      const isPlaylist = isPlaylistResource(currentUrl, upstreamContentType);

      // Branch A: HLS Playlist (.m3u8) Rewriting
      if (isPlaylist) {
        const chunks = [];
        upstreamRes.on('data', function (c) { chunks.push(c); });
        upstreamRes.on('end', function () {
          const manifestText = Buffer.concat(chunks).toString('utf8');
          const proxyPrefix = getProxyPrefix(req, localPort);
          const rewritten = rewriteManifest(manifestText, currentUrl, proxyPrefix);
          const rewrittenBuffer = Buffer.from(rewritten, 'utf8');

          res.writeHead(statusCode, Object.assign({}, CORS_HEADERS, {
            'Content-Type': 'application/vnd.apple.mpegurl; charset=utf-8',
            'Content-Length': rewrittenBuffer.length,
            'Cache-Control': 'no-cache, no-store, must-revalidate'
          }));

          if (req.method === 'HEAD') return res.end();
          res.end(rewrittenBuffer);
        });
        return;
      }

      // Branch B: Media Segments (.png, .mp4, fMP4 chunks) Streaming
      const responseHeaders = Object.assign({}, CORS_HEADERS);
      const pathname = parsed.pathname.toLowerCase();
      if (pathname.endsWith('.png') || pathname.endsWith('.mp4') || pathname.endsWith('.m4s') || pathname.endsWith('.ts')) {
        responseHeaders['Content-Type'] = 'video/mp4';
      } else if (pathname.endsWith('.vtt')) {
        responseHeaders['Content-Type'] = 'text/vtt; charset=utf-8';
      } else if (upstreamContentType) {
        responseHeaders['Content-Type'] = upstreamContentType;
      }

      if (upstreamRes.headers['content-length']) responseHeaders['Content-Length'] = upstreamRes.headers['content-length'];
      if (upstreamRes.headers['content-range']) responseHeaders['Content-Range'] = upstreamRes.headers['content-range'];
      if (upstreamRes.headers['cache-control']) responseHeaders['Cache-Control'] = upstreamRes.headers['cache-control'];
      else responseHeaders['Cache-Control'] = 'public, max-age=31536000, immutable';
      if (upstreamRes.headers['etag']) responseHeaders['ETag'] = upstreamRes.headers['etag'];
      if (upstreamRes.headers['last-modified']) responseHeaders['Last-Modified'] = upstreamRes.headers['last-modified'];

      res.writeHead(statusCode, responseHeaders);

      if (req.method === 'HEAD') return res.end();

      // Zero-buffering stream pipeline directly from upstream socket to client socket
      pipeline(upstreamRes, res, function (err) {
        if (err && err.code !== 'ERR_STREAM_PREMATURE_CLOSE' && err.message !== 'Premature close') {
          console.error('[HLS-Proxy] Pipeline error:', err.message);
        }
      });
    });

    upstreamReq.on('error', function (err) {
      if (!res.headersSent) {
        res.writeHead(502, Object.assign({}, CORS_HEADERS, { 'Content-Type': 'application/json' }));
        res.end(JSON.stringify({
          error: 'Proxy gateway error',
          message: err.message,
          url: currentUrl
        }));
      }
    });

    upstreamReq.setTimeout(15000, function () {
      upstreamReq.destroy();
    });

    upstreamReq.end();
  }

  executeRequest(targetUrl, 0);
}

module.exports = {
  handleHlsProxy: handleHlsProxy,
  rewriteManifest: rewriteManifest,
  resolveUrl: resolveUrl,
  unwrapProxyUrl: unwrapProxyUrl,
  isPlaylistResource: isPlaylistResource,
  validateTargetUrl: validateTargetUrl,
  getProxyPrefix: getProxyPrefix,
  default: {
    handleHlsProxy: handleHlsProxy,
    rewriteManifest: rewriteManifest,
    resolveUrl: resolveUrl,
    unwrapProxyUrl: unwrapProxyUrl,
    isPlaylistResource: isPlaylistResource,
    validateTargetUrl: validateTargetUrl,
    getProxyPrefix: getProxyPrefix
  }
};

/**
 * poc/service/index.js - Standalone On-Device Service Entry Point
 * Service ID: com.cinejoy.poc.service
 * 
 * Features:
 * - Triple-Shield Persistence Engine:
 *     Shield 1: activityManager.exitOnTimeout = false
 *     Shield 2: activityManager._createInternal('cinejoy_proxy_keepalive')
 *     Shield 3: Keepalive subscription method for webOS frontend
 * - Embedded HTTP streaming server binding strictly to 127.0.0.1:8088
 *   with automatic port fallback scanning (8088-8098).
 * - Full routing:
 *     GET /health or /api/health
 *     GET /api/servers
 *     GET /api/stream
 *     GET /hls/proxy
 *     GET /proxy/sub
 * - Luna bus registration for 'status' and 'keepalive' methods.
 * - Strict Node 12.22.2 compatibility (zero dependencies, no modern syntax).
 */

'use strict';

// Ensure webos-service resolves from TV system paths
if (!process.env.NODE_PATH) {
  process.env.NODE_PATH = '/usr/lib/nodejs:/usr/lib/node_modules';
  try {
    require('module').Module._initPaths();
  } catch (_) {}
}

const http = require('http');
const fs = require('fs');
const path = require('path');
const { URL } = require('url');

const resolver = require('./resolver');
const hlsProxy = require('./hls-proxy');
const httpClient = require('./http-client');

const DEFAULT_PORT = parseInt(process.env.PORT, 10) || 8088;
const DEFAULT_HOST = '127.0.0.1'; // Strictly loopback
const MAX_PORT_ATTEMPTS = 10;
const STATUS_FILE = path.join(__dirname, '.server-port');
const STATUS_JSON_FILE = path.join(__dirname, '.status.json');

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': '*',
  'Access-Control-Expose-Headers': 'Content-Length, Content-Range, Content-Type, Accept-Ranges',
  'Access-Control-Max-Age': '86400',
};

let activeServer = null;
let activePort = DEFAULT_PORT;

/**
 * Standardized JSON response helper
 */
function sendJson(res, statusCode, data) {
  const payload = Buffer.from(JSON.stringify(data), 'utf8');
  res.writeHead(statusCode, Object.assign({}, CORS_HEADERS, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': payload.length
  }));
  res.end(payload);
}

/**
 * Standardized error response helper
 */
function sendError(res, statusCode, message, details) {
  const body = { error: message, statusCode: statusCode };
  if (details) body.details = details;
  sendJson(res, statusCode, body);
}

/**
 * Converts SubRip (.srt) subtitles to WebVTT (.vtt) format
 */
function convertSrtToVtt(srtText) {
  if (srtText.trim().startsWith('WEBVTT')) {
    return srtText;
  }
  const normalized = srtText.replace(
    /(\d{2}:\d{2}:\d{2}),(\d{3})/g,
    '$1.$2'
  );
  return 'WEBVTT\n\n' + normalized.trim() + '\n';
}

/**
 * Main HTTP Request Dispatcher
 */
async function requestHandler(req, res) {
  // 1. Handle CORS Preflight OPTIONS
  if (req.method === 'OPTIONS') {
    res.writeHead(204, Object.assign({}, CORS_HEADERS, {
      'Content-Length': 0
    }));
    return res.end();
  }

  // Parse URL safely
  let parsedUrl;
  try {
    const host = (req.headers && req.headers.host) || ('127.0.0.1:' + activePort);
    parsedUrl = new URL(req.url, 'http://' + host);
  } catch (err) {
    return sendError(res, 400, 'Invalid Request URL');
  }

  const pathname = parsedUrl.pathname;
  const searchParams = parsedUrl.searchParams;

  try {
    // 2. Route: GET /health or /api/health
    if (pathname === '/health' || pathname === '/api/health') {
      return sendJson(res, 200, {
        status: 'ok',
        mode: 'on-device-service',
        serviceId: 'com.cinejoy.poc.service',
        uptime: process.uptime(),
        port: activePort,
        memory: process.memoryUsage(),
        timestamp: new Date().toISOString()
      });
    }

    // 3. Route: GET /api/servers
    if (pathname === '/api/servers') {
      try {
        const serverData = await resolver.getServers();
        return sendJson(res, 200, serverData);
      } catch (err) {
        return sendJson(res, 200, {
          servers: [
            { name: 'secret', '4k': true, status: 'ok' },
            { name: 'Nebula', '4k': false, status: 'ok' },
            { name: 'Lisbon', '4k': true, status: 'ok' },
            { name: 'Solara', '4k': false, status: 'ok' },
            { name: 'Athens', '4k': false, status: 'ok' }
          ]
        });
      }
    }

    // 4. Route: GET /api/stream
    if (pathname === '/api/stream') {
      const tmdbId = searchParams.get('tmdbId');
      const type = searchParams.get('type');
      const season = searchParams.get('season');
      const episode = searchParams.get('episode');
      const server = searchParams.get('server') || 'secret';

      if (!tmdbId || !type) {
        return sendError(res, 400, 'Missing required query parameters: tmdbId and type are required');
      }

      if (!/^\d+$/.test(tmdbId)) {
        return sendError(res, 400, 'Invalid tmdbId parameter: must be a positive integer');
      }

      if (type !== 'movie' && type !== 'tv') {
        return sendError(res, 400, "Invalid type parameter: must be 'movie' or 'tv'");
      }

      if (type === 'tv' && (!season || !episode)) {
        return sendError(res, 400, "Missing required query parameters: season and episode are required for type 'tv'");
      }

      const streamResult = await resolver.resolveStream({
        tmdbId: tmdbId,
        type: type,
        season: season,
        episode: episode,
        server: server
      });

      if (!streamResult || !streamResult.playlist) {
        return sendError(res, 502, 'Stream resolution failed: no playlist found');
      }

      // Construct local proxy stream URL
      const host = (req.headers && req.headers.host) || ('127.0.0.1:' + activePort);
      const encodedPlaylist = encodeURIComponent(streamResult.playlist);
      const streamUrl = 'http://' + host + '/hls/proxy?url=' + encodedPlaylist;

      // Build subtitles array
      const subtitles = [];
      if (Array.isArray(streamResult.captions)) {
        for (let i = 0; i < streamResult.captions.length; i++) {
          const cap = streamResult.captions[i];
          subtitles.push({
            label: cap.language || cap.id || 'English',
            srclang: cap.id || 'en',
            src: 'http://' + host + '/proxy/sub?url=' + encodeURIComponent(cap.url)
          });
        }
      }

      // Query external subtitles from subs.wing.st
      try {
        const extSubs = await resolver.fetchSubtitles({ tmdbId: tmdbId, type: type, season: season, episode: episode });
        if (Array.isArray(extSubs)) {
          for (let j = 0; j < extSubs.length; j++) {
            const s = extSubs[j];
            if (s.url) {
              const enc = encodeURIComponent(s.url);
              let exists = false;
              for (let k = 0; k < subtitles.length; k++) {
                if (subtitles[k].src.indexOf(enc) !== -1) {
                  exists = true;
                  break;
                }
              }
              if (!exists) {
                subtitles.push({
                  label: s.display || s.language || 'External',
                  srclang: s.language || 'en',
                  src: 'http://' + host + '/proxy/sub?url=' + enc
                });
              }
            }
          }
        }
      } catch (_) {
        // External subtitles failure is non-fatal
      }

      return sendJson(res, 200, {
        success: true,
        streamUrl: streamUrl,
        originalUrl: streamResult.playlist,
        server: streamResult.server || server,
        subtitles: subtitles
      });
    }

    // 5. Route: GET /hls/proxy
    if (pathname === '/hls/proxy') {
      const targetUrl = searchParams.get('url');
      if (!targetUrl) {
        return sendError(res, 400, "Missing 'url' query parameter for HLS proxy");
      }
      return hlsProxy.handleHlsProxy(req, res, targetUrl, activePort);
    }

    // 6. Route: GET /proxy/sub
    if (pathname === '/proxy/sub') {
      const subUrl = searchParams.get('url');
      if (!subUrl) {
        return sendError(res, 400, "Missing 'url' query parameter for subtitle proxy");
      }

      try {
        const subRes = await httpClient.request(subUrl, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 Chrome/108.0.5359.211',
            'Origin': 'https://cinejoy.pk',
            'Referer': 'https://cinejoy.pk/'
          },
          timeout: 10000
        });

        if (subRes.statusCode < 200 || subRes.statusCode >= 300) {
          return sendError(res, 502, 'Failed to fetch remote subtitle: HTTP ' + subRes.statusCode);
        }

        const rawText = subRes.body.toString('utf8');
        const vttContent = convertSrtToVtt(rawText);
        const buffer = Buffer.from(vttContent, 'utf8');

        res.writeHead(200, Object.assign({}, CORS_HEADERS, {
          'Content-Type': 'text/vtt; charset=utf-8',
          'Content-Length': buffer.length
        }));
        return res.end(buffer);
      } catch (err) {
        return sendError(res, 502, 'Failed to fetch subtitle', err.message);
      }
    }

    // 7. Route: 404 Fallthrough
    return sendError(res, 404, 'Endpoint Not Found', { path: pathname });
  } catch (err) {
    console.error('[cinejoy-service] Error handling ' + req.method + ' ' + pathname + ':', err);
    return sendError(res, 500, 'Internal Server Error', err.message);
  }
}

/**
 * Writes active port and metadata to status files
 */
function writeStatusFiles(port) {
  try {
    fs.writeFileSync(STATUS_FILE, port.toString(), 'utf8');
    const statusMeta = {
      port: port,
      host: DEFAULT_HOST,
      pid: process.pid,
      startedAt: new Date().toISOString(),
      serviceId: 'com.cinejoy.poc.service'
    };
    fs.writeFileSync(STATUS_JSON_FILE, JSON.stringify(statusMeta, null, 2), 'utf8');
  } catch (err) {
    console.warn('[cinejoy-service] Warning: Could not write status file:', err.message);
  }
}

/**
 * Removes status files upon shutdown
 */
function removeStatusFiles() {
  try {
    if (fs.existsSync(STATUS_FILE)) fs.unlinkSync(STATUS_FILE);
    if (fs.existsSync(STATUS_JSON_FILE)) fs.unlinkSync(STATUS_JSON_FILE);
  } catch (_) {}
}

/**
 * Starts the HTTP server with port collision detection and fallback (8088-8098)
 */
function startServer(initialPort, host) {
  initialPort = initialPort || DEFAULT_PORT;
  host = host || DEFAULT_HOST;

  return new Promise(function (resolve, reject) {
    let currentPort = initialPort;
    let attempts = 0;

    function tryListen() {
      const server = http.createServer(requestHandler);

      server.on('error', function (err) {
        if (err.code === 'EADDRINUSE') {
          attempts++;
          console.warn('[cinejoy-service] Port ' + currentPort + ' in use, trying ' + (currentPort + 1) + '...');
          currentPort++;
          if (attempts >= MAX_PORT_ATTEMPTS) {
            return reject(new Error('Could not bind to any port in range ' + initialPort + '-' + (currentPort - 1)));
          }
          setTimeout(tryListen, 50);
        } else {
          reject(err);
        }
      });

      server.on('listening', function () {
        activeServer = server;
        activePort = currentPort;
        writeStatusFiles(activePort);
        console.log('[cinejoy-service] HTTP server listening on http://' + host + ':' + activePort + ' (PID: ' + process.pid + ')');
        resolve({ server: server, port: activePort });
      });

      server.listen(currentPort, host);
    }

    tryListen();
  });
}

/**
 * Stops the active HTTP server cleanly
 */
function stopServer() {
  return new Promise(function (resolve) {
    removeStatusFiles();
    if (activeServer) {
      if (typeof activeServer.closeAllConnections === 'function') {
        activeServer.closeAllConnections();
      }
      activeServer.close(function () {
        activeServer = null;
        resolve();
      });
    } else {
      resolve();
    }
  });
}

/**
 * Initializes webOS Luna Bus Service registration with Triple-Shield Persistence
 */
function initWebosService() {
  let Service = null;
  try {
    Service = require('webos-service');
  } catch (err) {
    console.warn('[cinejoy-service] webos-service module not found; running standalone HTTP mode.');
    return null;
  }

  const service = new Service('com.cinejoy.poc.service');

  // Shield 1: Disable automatic exitOnTimeout in ActivityManager
  if (service.activityManager) {
    service.activityManager.exitOnTimeout = false;
    console.log('[cinejoy-service] Shield 1 active: exitOnTimeout set to false');

    // Shield 2: Create a permanent internal activity that never completes
    service.activityManager._createInternal('cinejoy_proxy_keepalive', function (act) {
      console.log('[cinejoy-service] Shield 2 active: internal activity created:', act.activityId);
    });
  }

  // Shield 3: Subscription keepalive endpoint for the frontend
  const activeSubscriptions = {};
  service.register('keepalive', function (message) {
    if (message.isSubscription) {
      activeSubscriptions[message.uniqueToken] = message;
      message.respond({
        returnValue: true,
        status: 'subscribed',
        port: activePort,
        uptime: process.uptime()
      });
    } else {
      message.respond({
        returnValue: true,
        status: 'running',
        port: activePort,
        uptime: process.uptime()
      });
    }
  }, function (message) {
    delete activeSubscriptions[message.uniqueToken];
  });

  // Standard status reporting method
  service.register('status', function (message) {
    message.respond({
      returnValue: true,
      status: 'running',
      port: activePort,
      serviceId: 'com.cinejoy.poc.service',
      uptime: process.uptime(),
      rssBytes: process.memoryUsage().rss
    });
  });

  console.log('[cinejoy-service] Registered Luna methods: keepalive, status');
  return service;
}

// Clean exit handlers
process.on('SIGTERM', async function () {
  console.log('[cinejoy-service] Received SIGTERM, shutting down...');
  await stopServer();
  process.exit(0);
});

process.on('SIGINT', async function () {
  console.log('[cinejoy-service] Received SIGINT, shutting down...');
  await stopServer();
  process.exit(0);
});

process.on('exit', function () {
  removeStatusFiles();
});

// Bootstrapping sequence
startServer(DEFAULT_PORT, DEFAULT_HOST).then(function () {
  initWebosService();
}).catch(function (err) {
  console.error('[cinejoy-service] Fatal startup error:', err);
  process.exit(1);
});

module.exports = {
  startServer: startServer,
  stopServer: stopServer,
  getActivePort: function () { return activePort; },
  requestHandler: requestHandler,
  CORS_HEADERS: CORS_HEADERS
};

